/**
 * Voxel.io Granny Game Mode
 * Stealth horror escape from voxel house: Granny sound detection AI, puzzles, keys, and 5-day cycle.
 */

import { GameModeBase } from './GameModeBase.js';

export class GrannyMode extends GameModeBase {
  constructor(options = {}) {
    super('granny', 'Granny', options);

    this.currentDay = 1;
    this.maxDays = 5;
    this.noiseMeter = 0; // 0 to 100
    this.isHiding = false;
    this.grannyState = 'PATROL'; // 'PATROL' | 'INVESTIGATING' | 'CHASING'
    this.grannyPos = [0, 65, 15];
    this.grannySpeed = 3.2;
    this.lastNoiseLocation = null;

    // Items needed for escape
    this.escapes = {
      frontDoor: {
        padlockUnlocked: false,
        wiresCut: false,
        planksRemoved: false,
        masterUnlocked: false,
      },
      car: {
        batteryInstalled: false,
        sparkPlugInstalled: false,
        gasFilled: false,
        carKeyUsed: false,
      },
    };

    this.inventory = [];
    this.keysFound = new Set();
  }

  onStart() {
    this.currentDay = 1;
    this.noiseMeter = 0;
    this.isHiding = false;
    this.grannyState = 'PATROL';
    this.grannyPos = [0, 65, 15];

    if (this.engine?.world) {
      this.generateGrannyHouse();
    }
  }

  generateGrannyHouse() {
    const world = this.engine.world;
    if (!world?.setBlock) return;

    // House floor at y=64 (18x18 room)
    for (let x = -9; x <= 9; x++) {
      for (let z = -9; z <= 9; z++) {
        world.setBlock(x, 64, z, 5); // wooden floor
        world.setBlock(x, 70, z, 5); // ceiling
        // Perimeter walls
        if (Math.abs(x) === 9 || Math.abs(z) === 9) {
          for (let y = 65; y <= 69; y++) {
            world.setBlock(x, y, z, 98); // stone walls
          }
        }
      }
    }

    // Front Door at [0, 65, -9]
    world.setBlock(0, 65, -9, 64);
    world.setBlock(0, 66, -9, 64);

    // Bed for hiding under at [-6, 65, -5]
    world.setBlock(-6, 65, -5, 35);
    // Wardrobe closet at [6, 65, -5]
    world.setBlock(6, 65, -5, 17);
  }

  makeNoise(amount, location = null) {
    this.noiseMeter = Math.min(100, this.noiseMeter + amount);
    const loc = location || this.engine?.localPlayer?.position || [0, 65, 0];
    this.lastNoiseLocation = [...loc];

    if (this.noiseMeter >= 40) {
      this.grannyState = 'INVESTIGATING';
      this.ui?.showNotification?.('🔊 Granny heard that noise!', 'warning');
    }
  }

  onUpdate(dt) {
    // Noise decay
    if (this.noiseMeter > 0) {
      this.noiseMeter = Math.max(0, this.noiseMeter - dt * 8.0);
    }

    // Tick Granny AI
    this.updateGrannyAI(dt);
  }

  updateGrannyAI(dt) {
    const playerPos = this.engine?.localPlayer?.position || [0, 65, 0];
    const distToPlayer = Math.hypot(
      playerPos[0] - this.grannyPos[0],
      playerPos[2] - this.grannyPos[2]
    );

    // Check line of sight
    if (!this.isHiding && distToPlayer < 12.0) {
      this.grannyState = 'CHASING';
    }

    if (this.grannyState === 'CHASING') {
      const speed = this.grannySpeed * 1.5;
      const dirX = (playerPos[0] - this.grannyPos[0]) / (distToPlayer || 1);
      const dirZ = (playerPos[2] - this.grannyPos[2]) / (distToPlayer || 1);
      this.grannyPos[0] += dirX * speed * dt;
      this.grannyPos[2] += dirZ * speed * dt;

      if (distToPlayer < 1.8 && !this.isHiding) {
        // Player caught!
        this.onPlayerCaught();
      }
    } else if (this.grannyState === 'INVESTIGATING' && this.lastNoiseLocation) {
      const distToNoise = Math.hypot(
        this.lastNoiseLocation[0] - this.grannyPos[0],
        this.lastNoiseLocation[2] - this.grannyPos[2]
      );
      if (distToNoise < 1.5) {
        this.grannyState = 'PATROL';
        this.lastNoiseLocation = null;
      } else {
        const dirX = (this.lastNoiseLocation[0] - this.grannyPos[0]) / distToNoise;
        const dirZ = (this.lastNoiseLocation[2] - this.grannyPos[2]) / distToNoise;
        this.grannyPos[0] += dirX * this.grannySpeed * dt;
        this.grannyPos[2] += dirZ * this.grannySpeed * dt;
      }
    }
  }

  onPlayerCaught() {
    this.currentDay++;
    if (this.currentDay > this.maxDays) {
      this.state = 'ENDED';
      this.ui?.showNotification?.('💀 GAME OVER! Granny eliminated you on Day 5.', 'danger');
    } else {
      this.grannyPos = [0, 65, 15];
      this.grannyState = 'PATROL';
      this.noiseMeter = 0;
      this.ui?.showNotification?.(`🩸 Caught! You wake up on DAY ${this.currentDay}...`, 'danger');
    }
  }

  unlockFrontDoorStep(step) {
    if (this.escapes.frontDoor[step] !== undefined) {
      this.escapes.frontDoor[step] = true;
      this.ui?.showNotification?.(`🔓 Front Door progress: ${step} completed!`, 'success');
      this.checkEscape();
    }
  }

  checkEscape() {
    const f = this.escapes.frontDoor;
    if (f.padlockUnlocked && f.wiresCut && f.planksRemoved && f.masterUnlocked) {
      this.state = 'ENDED';
      this.ui?.showNotification?.('🏆 CONGRATULATIONS! You unlocked the Front Door and ESCAPED!', 'success');
    }
  }

  getHudData() {
    return {
      mode: 'Granny',
      state: this.state,
      day: this.currentDay,
      maxDays: this.maxDays,
      noise: Math.round(this.noiseMeter),
      grannyAlert: this.grannyState,
      isHiding: this.isHiding,
      frontDoorProgress: Object.values(this.escapes.frontDoor).filter(Boolean).length + '/4',
    };
  }
}
