/**
 * Voxel.io Manhunt Game Mode
 * Speedrunner vs Hunter(s) asymmetric survival with tracking compass and portal objectives.
 */

import { GameModeBase } from './GameModeBase.js';

export class ManhuntMode extends GameModeBase {
  constructor(options = {}) {
    super('manhunt', 'Manhunt', options);

    this.role = options.role || 'runner'; // 'runner' | 'hunter'
    this.runnerPos = [0, 65, 0];
    this.hunterPositions = new Map();
    this.runnerAlive = true;
    this.enderEyesCollected = 0;
    this.enderEyesNeeded = 12;
    this.portalActivated = false;
    this.bossHp = 200;

    this.compassBearing = 0; // Degrees
    this.compassDistance = 0; // Blocks
  }

  onStart() {
    this.runnerAlive = true;
    this.enderEyesCollected = 0;
    this.portalActivated = false;
    this.bossHp = 200;

    if (this.engine?.world) {
      this.generateManhuntWorld();
    }

    // Spawn 2 AI Hunters if player is Runner, or 1 AI Speedrunner if player is Hunter
    if (this.role === 'runner') {
      const hunterNames = ['HunterAlpha', 'HunterBravo'];
      hunterNames.forEach((name, i) => {
        const bot = {
          id: `hunter_${i + 1}`,
          name: name,
          pos: [i === 0 ? 30 : -30, 65, 30],
          hp: 20,
          compassTarget: [0, 65, 0],
        };
        this.bots.push(bot);
      });
    } else {
      // Player is hunter, spawn AI runner
      const runnerBot = {
        id: 'speedrunner_bot',
        name: 'DreamRunner',
        pos: [0, 65, -50],
        hp: 20,
        resources: 0,
      };
      this.bots.push(runnerBot);
    }
  }

  generateManhuntWorld() {
    const world = this.engine.world;
    if (!world?.setBlock) return;

    // Natural landscape terrain
    for (let x = -30; x <= 30; x++) {
      for (let z = -30; z <= 30; z++) {
        world.setBlock(x, 63, z, 1); // stone
        world.setBlock(x, 64, z, 2); // grass
      }
    }

    // Void / End Portal Frame at [0, 64, 80]
    for (let x = -2; x <= 2; x++) {
      for (let z = 78; z <= 82; z++) {
        if (Math.abs(x) === 2 || Math.abs(z - 80) === 2) {
          world.setBlock(x, 64, z, 120); // End portal frame
        }
      }
    }
  }

  onUpdate(dt) {
    if (!this.runnerAlive) return;

    // Get current runner position
    if (this.role === 'runner') {
      const p = this.engine?.localPlayer?.position || [0, 65, 0];
      this.runnerPos = [...p];
    } else {
      const runnerBot = this.bots.find((b) => b.id === 'speedrunner_bot');
      if (runnerBot) {
        this.runnerPos = [...runnerBot.pos];
      }
    }

    // Update tracking compass
    const observerPos = this.engine?.localPlayer?.position || [0, 65, 0];
    const dx = this.runnerPos[0] - observerPos[0];
    const dz = this.runnerPos[2] - observerPos[2];
    this.compassDistance = Math.round(Math.hypot(dx, dz));
    this.compassBearing = Math.round((Math.atan2(dx, dz) * 180) / Math.PI);

    // Tick AI hunters or runners
    this.updateManhuntBots(dt);
  }

  updateManhuntBots(dt) {
    if (this.role === 'runner') {
      // AI Hunters track and pursue the runner
      for (const hunter of this.bots) {
        const dx = this.runnerPos[0] - hunter.pos[0];
        const dz = this.runnerPos[2] - hunter.pos[2];
        const dist = Math.hypot(dx, dz);
        if (dist > 2) {
          hunter.pos[0] += (dx / dist) * 4.2 * dt;
          hunter.pos[2] += (dz / dist) * 4.2 * dt;
        } else {
          // Attack runner
          this.engine?.localPlayer?.takeDamage?.(4, hunter.id);
          this.ui?.showNotification?.(`${hunter.name} struck you!`, 'combat');
        }
      }
    } else {
      // AI runner paths towards portal
      const runner = this.bots.find((b) => b.id === 'speedrunner_bot');
      if (runner) {
        runner.pos[2] += 3.8 * dt; // Run towards portal at z=80
        if (runner.pos[2] >= 75) {
          this.portalActivated = true;
        }
      }
    }
  }

  findEnderEye() {
    if (this.enderEyesCollected < this.enderEyesNeeded) {
      this.enderEyesCollected++;
      this.ui?.showNotification?.(`👁️ Found Eye of Ender (${this.enderEyesCollected}/${this.enderEyesNeeded})!`, 'info');
      if (this.enderEyesCollected === this.enderEyesNeeded) {
        this.activatePortal();
      }
    }
  }

  activatePortal() {
    this.portalActivated = true;
    this.ui?.showNotification?.('🌌 THE END PORTAL HAS BEEN ACTIVATED!', 'success');
  }

  onPlayerDeath(playerId, killerId, cause) {
    if ((this.role === 'runner' && playerId === 'local_player') || playerId === 'speedrunner_bot') {
      this.runnerAlive = false;
      this.state = 'ENDED';
      this.ui?.showNotification?.('🏹 HUNTERS WIN! Speedrunner was eliminated.', 'danger');
    }
  }

  getHudData() {
    return {
      mode: 'Manhunt',
      state: this.state,
      role: this.role.toUpperCase(),
      compassBearing: this.compassBearing,
      compassDistance: this.compassDistance,
      eyes: `${this.enderEyesCollected}/${this.enderEyesNeeded}`,
      portal: this.portalActivated ? 'ACTIVE' : 'INACTIVE',
      runnerAlive: this.runnerAlive,
    };
  }
}
