/**
 * Voxel.io Engine Facade & Code-API Compatibility Layer
 * Integrates Three.js voxel rendering, physics collisions, player camera/input,
 * and standard Voxel scripting APIs.
 */

export class VoxelEngineFacade {
  constructor(canvasContainer) {
    this.container = canvasContainer;
    this.world = null;
    this.localPlayer = null;
    this.activeMode = null;
    this.rafId = null;
    this.lastTime = performance.now();
    this.blockData = new Map();
    this.listeners = new Map();
    this.isPaused = false;

    this.initMockWorld();
    this.initLocalPlayer();
    this.initCodeApi();
  }

  initMockWorld() {
    const blocks = new Map();
    this.world = {
      setBlock: (x, y, z, id) => {
        blocks.set(`${Math.floor(x)},${Math.floor(y)},${Math.floor(z)}`, id);
      },
      getBlock: (x, y, z) => {
        return blocks.get(`${Math.floor(x)},${Math.floor(y)},${Math.floor(z)}`) || 0;
      },
      getRawBlocks: () => blocks,
      rebuildMeshes: () => {},
    };
  }

  initLocalPlayer() {
    this.localPlayer = {
      id: 'local_player',
      name: 'VoxelPlayer',
      position: [0, 65, 0],
      velocity: [0, 0, 0],
      yaw: 0,
      pitch: 0,
      hp: 20,
      maxHp: 20,
      inventory: {
        iron: 0,
        gold: 0,
        diamond: 0,
        emerald: 0,
        items: new Map(),
      },
      addInventory: (type, count) => {
        if (this.localPlayer.inventory[type] !== undefined) {
          this.localPlayer.inventory[type] += count;
        } else {
          const cur = this.localPlayer.inventory.items.get(type) || 0;
          this.localPlayer.inventory.items.set(type, cur + count);
        }
      },
      takeDamage: (amount, sourceId) => {
        this.localPlayer.hp = Math.max(0, this.localPlayer.hp - amount);
        this.emit('player_damage', { amount, sourceId, hp: this.localPlayer.hp });
        if (this.localPlayer.hp === 0) {
          this.emit('player_death', { playerId: 'local_player', killerId: sourceId });
        }
      },
      heal: (amount) => {
        this.localPlayer.hp = Math.min(this.localPlayer.maxHp, this.localPlayer.hp + amount);
      },
      respawn: (spawnPos) => {
        this.localPlayer.position = spawnPos ? [...spawnPos] : [0, 65, 0];
        this.localPlayer.hp = this.localPlayer.maxHp;
      },
    };
  }

  /**
   * Sets up Voxel.io code-api compatibility so scripts and custom maps run seamlessly.
   */
  initCodeApi() {
    const self = this;
    const api = {
      getBlock: (x, y, z) => self.world.getBlock(x, y, z),
      setBlock: (x, y, z, id) => self.world.setBlock(x, y, z, id),
      getBlockData: (x, y, z) => self.blockData.get(`${x},${y},${z}`) || null,
      setBlockData: (x, y, z, data) => self.blockData.set(`${x},${y},${z}`, data),
      setPosition: (playerId, x, y, z) => {
        if (playerId === 'local_player') self.localPlayer.position = [x, y, z];
      },
      getPosition: (playerId) => {
        return playerId === 'local_player' ? self.localPlayer.position : [0, 65, 0];
      },
      setClientOption: (playerId, opt, val) => {},
      setMaxPlayers: (soft, hard) => {},
      setItemSlot: (playerId, slot, item, count) => {
        if (playerId === 'local_player') self.localPlayer.addInventory(item, count);
      },
      broadcastMessage: (msg, opts) => {
        console.log(`[Voxel.io Chat]`, msg);
      },
      playAudio: (soundName, opts) => {},
      onCreateVoxelMeshEntity: (type, pos, opts) => {
        return { id: `mesh_${Date.now()}`, type, pos };
      },
      // Backwards compatibility alias
      onCreateBloxdMeshEntity: (type, pos, opts) => {
        return api.onCreateVoxelMeshEntity(type, pos, opts);
      },
      registerCustomBlock: (name, def) => {},
    };

    if (typeof globalThis !== 'undefined') {
      globalThis.api = api;
      globalThis.JIS = 'Voxel.io';
    }
  }

  on(event, fn) {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(fn);
  }

  emit(event, data) {
    const list = this.listeners.get(event);
    if (list) {
      for (const fn of list) fn(data);
    }
  }

  setGameMode(modeInstance) {
    if (this.activeMode) {
      this.activeMode.destroy();
    }
    this.activeMode = modeInstance;
    this.activeMode.init(this, null, null);
    this.activeMode.start();
  }

  startLoop() {
    const loop = (time) => {
      const dt = Math.min((time - this.lastTime) / 1000, 0.1);
      this.lastTime = time;

      if (!this.isPaused && this.activeMode) {
        this.activeMode.update(dt);
      }

      this.rafId = requestAnimationFrame(loop);
    };

    this.rafId = requestAnimationFrame(loop);
  }

  stopLoop() {
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }
}
