/**
 * Voxel.io GameModeBase
 * Abstract base class for all unified game modes in Voxel.io.
 */

export class GameModeBase {
  constructor(id, name, options = {}) {
    this.id = id;
    this.name = name;
    this.options = options;
    this.engine = null;
    this.net = null;
    this.ui = null;
    this.isRunning = false;
    this.players = new Map();
    this.bots = [];
    this.elapsedTime = 0;
    this.state = 'LOBBY'; // 'LOBBY' | 'PLAYING' | 'ENDED'
  }

  /**
   * Initializes the game mode with engine, network manager, and UI.
   */
  init(engine, net, ui) {
    this.engine = engine;
    this.net = net;
    this.ui = ui;
    console.log(`[Voxel.io] Initialized game mode: ${this.name} (${this.id})`);
  }

  /**
   * Called when player starts or enters the match.
   */
  start() {
    this.isRunning = true;
    this.state = 'PLAYING';
    this.elapsedTime = 0;
    this.onStart();
  }

  onStart() {}

  /**
   * Game loop update.
   */
  update(dt) {
    if (!this.isRunning) return;
    this.elapsedTime += dt;
    this.onUpdate(dt);
  }

  onUpdate(dt) {}

  /**
   * Handle player attack event.
   */
  handleAttack(attackerId, targetId, weapon) {
    return this.onPlayerAttack(attackerId, targetId, weapon);
  }

  onPlayerAttack(attackerId, targetId, weapon) {}

  /**
   * Handle block placed or broken.
   */
  handleBlockChange(x, y, z, oldType, newType, sourcePlayerId) {
    return this.onBlockChange(x, y, z, oldType, newType, sourcePlayerId);
  }

  onBlockChange(x, y, z, oldType, newType, sourcePlayerId) {}

  /**
   * Handle player death.
   */
  handlePlayerDeath(playerId, killerId, cause) {
    this.onPlayerDeath(playerId, killerId, cause);
  }

  onPlayerDeath(playerId, killerId, cause) {}

  /**
   * Return mode-specific HUD status or objective data.
   */
  getHudData() {
    return {
      mode: this.name,
      state: this.state,
      time: Math.floor(this.elapsedTime),
      players: this.players.size + (this.engine?.localPlayer ? 1 : 0),
    };
  }

  /**
   * Cleanup resources when exiting mode.
   */
  destroy() {
    this.isRunning = false;
    this.state = 'ENDED';
    this.bots = [];
    this.players.clear();
    this.onDestroy();
    console.log(`[Voxel.io] Cleaned up game mode: ${this.name}`);
  }

  onDestroy() {}
}
