/**
 * Voxel.io Main Application Entry Point
 * Bootstraps engine, UI, network layers (WebRTC P2P + LAN Discovery), and offline PWA mode.
 */

import './style.css';
import { VoxelEngineFacade } from './engine/VoxelEngineFacade.js';
import { VoxelHubUI } from './ui/VoxelHubUI.js';
import { createGameInstance } from './modes/GameRoster.js';
import {
  VoxelNetManager,
  LanDiscovery,
  WebRTCAdapter,
  LocalGameLoop,
  registerVoxelOfflineWorker,
} from './net/index.js';

class VoxelApp {
  constructor() {
    this.container = document.getElementById('app');
    this.engine = null;
    this.ui = null;
    this.net = null;
    this.lan = null;
    this.webrtc = null;
    this.localLoop = null;
    this.activeMode = null;
  }

  async init() {
    console.log('🚀 Initializing Voxel.io Client...');

    // 1. Initialize Network Subsystems
    this.lan = new LanDiscovery();
    this.webrtc = new WebRTCAdapter();
    this.localLoop = new LocalGameLoop();
    this.net = new VoxelNetManager(null, {
      lan: this.lan,
      webrtc: this.webrtc,
      localLoop: this.localLoop,
    });

    // 2. Initialize Voxel Engine Facade
    this.engine = new VoxelEngineFacade(this.container);

    // 3. Initialize UI & Event Handlers
    this.ui = new VoxelHubUI(this.container, {
      onSelectMode: (modeId) => this.launchGameMode(modeId),
      onHostRoom: (modeId) => this.hostMultiplayerRoom(modeId),
      onJoinRoom: (roomCode) => this.joinMultiplayerRoom(roomCode),
      onDirectJoin: (address) => this.connectDirectAddress(address),
      onLeaveToLobby: () => this.leaveToLobby(),
    });

    // 4. Start LAN discovery listener & broadcast
    this.lan.onDiscovered((rooms) => {
      this.ui.updateLanRooms(rooms);
    });
    this.lan.start();

    // 5. Register Offline ServiceWorker
    try {
      await registerVoxelOfflineWorker('./sw.js');
    } catch (e) {
      console.warn('[Voxel.io] ServiceWorker registration skipped:', e);
    }

    // 6. Connect Network packet router to engine world
    this.net.onPacket('BLOCK_PLACE', (payload) => {
      this.engine.world?.setBlock?.(payload.x, payload.y, payload.z, payload.blockType);
    });

    this.net.onPacket('BLOCK_BREAK', (payload) => {
      this.engine.world?.setBlock?.(payload.x, payload.y, payload.z, 0);
    });

    // 7. Start Engine Render & Tick Loop
    this.engine.startLoop();
    this.startHudSync();

    console.log('✅ Voxel.io Client Ready!');
  }

  launchGameMode(modeId, options = {}) {
    console.log(`[Voxel.io] Launching game mode: ${modeId}`);
    try {
      this.activeMode = createGameInstance(modeId, options);
      this.engine.setGameMode(this.activeMode);
      this.ui.showInGameView(this.activeMode);
      this.ui.showNotification(`Loaded ${this.activeMode.name}! Have fun!`, 'success');
    } catch (err) {
      console.error(`[Voxel.io] Failed to launch mode ${modeId}:`, err);
      this.ui.showNotification(`Error launching ${modeId}: ${err.message}`, 'danger');
    }
  }

  hostMultiplayerRoom(modeId = 'bedwars') {
    const roomCode = `VOXEL-${Math.floor(1000 + Math.random() * 9000)}`;
    console.log(`[Voxel.io] Hosting Room ${roomCode}...`);

    // Broadcast LAN beacon
    this.lan.broadcastBeacon({
      app: 'voxel-io-lan',
      roomCode: roomCode,
      hostName: 'Voxel Host',
      gameMode: modeId,
      port: 8766,
      ip: '127.0.0.1',
      players: 1,
      maxPlayers: 8,
    });

    this.launchGameMode(modeId, { isHost: true, roomCode });
    this.ui.showNotification(`Hosted Room ${roomCode} on LAN & WebRTC!`, 'success');
  }

  joinMultiplayerRoom(roomCode) {
    console.log(`[Voxel.io] Joining Room ${roomCode}...`);
    this.ui.showNotification(`Connecting to room ${roomCode}...`, 'info');
    // Launch Bedwars or appropriate mode in client mode
    this.launchGameMode('bedwars', { isHost: false, roomCode });
  }

  connectDirectAddress(address) {
    console.log(`[Voxel.io] Connecting to Direct IP: ${address}...`);
    const [ip, portStr] = address.split(':');
    const port = parseInt(portStr, 10) || 8766;
    if (this.lan.validateAddress ? this.lan.validateAddress(ip, port) : true) {
      this.ui.showNotification(`Connecting to LAN server at ${address}...`, 'info');
      this.launchGameMode('bedwars', { isHost: false, directIp: address });
    } else {
      this.ui.showNotification(`Invalid IP address: ${address}`, 'danger');
    }
  }

  leaveToLobby() {
    if (this.activeMode) {
      this.activeMode.destroy();
      this.activeMode = null;
    }
    this.ui.showHubView();
    this.ui.showNotification('Returned to Lobby.', 'info');
  }

  startHudSync() {
    setInterval(() => {
      if (this.activeMode && this.ui.activeView === 'IN_GAME') {
        const hudData = this.activeMode.getHudData();
        this.ui.updateHud(hudData, this.engine.localPlayer);
      }
    }, 100);
  }
}

// Bootstrap app on DOM ready
window.addEventListener('DOMContentLoaded', () => {
  const app = new VoxelApp();
  app.init().catch(console.error);
  window.voxelApp = app;
});
