/**
 * shared-net-offline/VoxelNetManager.js
 * Master Networking & Offline Facade for Voxel.io clean slate.
 * 
 * Features:
 * - Dynamic transport switching: WebRTC P2P (primary zero-server mode) <-> LAN Direct <-> Offline Loopback
 * - Desktop UDP & Browser BroadcastChannel discovery management
 * - High-level gameplay packet broadcasting (blocks, transforms, damage, chat, game state)
 * - Seamless offline solo fallback
 */

import { WebRTCAdapter } from './WebRTCAdapter.js';
import { LanDiscovery, validateLanAddress, formatDirectUrl } from './LanDiscovery.js';

export class VoxelNetManager {
  /**
   * @param {Object} [gameManager=null] Reference to local game instance
   * @param {Object} [options={}]
   */
  constructor(gameManager = null, options = {}) {
    this.gm = gameManager;
    this.options = options;

    // Sub-modules
    this.rtcAdapter = new WebRTCAdapter(options);
    this.lanDiscovery = new LanDiscovery(options);

    // Current State
    this.activeTransport = 'offline'; // 'webrtc' | 'lan' | 'offline' | 'none'
    this.isHost = true;
    this.roomCode = 'LOCAL-SOLO';
    this.clientId = 'player_local';
    this.hudBadge = 'Offline Solo';

    // Packet dispatch table
    this.packetListeners = new Map(); // type -> Set<Function>

    this.setupListeners();
  }

  setupListeners() {
    const dispatch = (packet) => this.handleIncomingPacket(packet);
    this.rtcAdapter.onPacket('*', dispatch);
  }

  /**
   * Returns human-readable transport name.
   */
  getTransportName() {
    switch (this.activeTransport) {
      case 'webrtc':
        return this.isHost ? 'WebRTC P2P (Host)' : 'WebRTC P2P (Peer)';
      case 'lan':
        return this.isHost ? 'LAN (Host)' : 'LAN Direct';
      case 'offline':
        return 'Offline Solo / Bots';
      default:
        return 'Disconnected';
    }
  }

  /**
   * 1. Start Serverless WebRTC P2P Room (Host)
   */
  async hostP2PRoom(options = {}) {
    this.activeTransport = 'webrtc';
    this.isHost = true;
    const roomCode = await this.rtcAdapter.createRoom(options);
    this.roomCode = roomCode;
    this.clientId = roomCode;
    this.hudBadge = `P2P Host [${roomCode}]`;

    // Also advertise on LAN via BroadcastChannel / UDP
    this.lanDiscovery.startBroadcast({
      roomCode,
      hostName: options.hostName || "Host's Arena",
      gameMode: options.gameMode || 'voxel-io',
      map: options.map || 'default',
    });

    return { roomCode, transport: 'webrtc' };
  }

  /**
   * 2. Join Serverless WebRTC P2P Room (Peer)
   */
  async joinP2PRoom(roomCode, options = {}) {
    this.activeTransport = 'webrtc';
    this.isHost = false;
    await this.rtcAdapter.joinRoom(roomCode, options);
    this.roomCode = roomCode;
    this.clientId = this.rtcAdapter.clientId;
    this.hudBadge = `P2P Peer [${roomCode}]`;
    return { roomCode, transport: 'webrtc' };
  }

  /**
   * 3. Join LAN Direct via IP and Port
   */
  async joinDirectLan(ip, port, options = {}) {
    if (!validateLanAddress(ip, port)) {
      throw new Error(`Invalid IPv4 address or port: ${ip}:${port}`);
    }
    const directUrl = formatDirectUrl(ip, port);
    this.activeTransport = 'lan';
    this.isHost = false;
    this.roomCode = `LAN-${ip}:${port}`;
    this.hudBadge = `LAN [${ip}:${port}]`;

    // WebRTC or WebSocket bridge to host
    return { url: directUrl, transport: 'lan' };
  }

  /**
   * 4. Start Offline Solo / Bot Match
   */
  startOfflineSolo() {
    this.disconnect();
    this.activeTransport = 'offline';
    this.isHost = true;
    this.roomCode = 'LOCAL-SOLO';
    this.clientId = 'player_offline';
    this.hudBadge = 'Offline Solo';
    return { status: 'offline_ready' };
  }

  /**
   * Disconnects active sessions.
   */
  disconnect() {
    this.lanDiscovery.stopBroadcast();
    this.lanDiscovery.stopDiscovery();
    this.rtcAdapter.disconnect();
    this.activeTransport = 'offline';
    this.isHost = true;
    this.hudBadge = 'Offline Solo';
  }

  /**
   * Broadcasts gameplay packet through active transport.
   */
  sendPacket(type, payload = {}) {
    if (this.activeTransport === 'webrtc') {
      return this.rtcAdapter.sendPacket(type, payload);
    }
    if (this.activeTransport === 'offline') {
      // Loopback directly to local game loop if needed
      return true;
    }
    return false;
  }

  // --- Convenience Gameplay Broadcasters ---

  broadcastBlockPlace(x, y, z, blockType) {
    return this.sendPacket('BLOCK_PLACE', { x, y, z, blockType });
  }

  broadcastBlockBreak(x, y, z) {
    return this.sendPacket('BLOCK_BREAK', { x, y, z });
  }

  broadcastPlayerTransform(x, y, z, yaw = 0, pitch = 0, vx = 0, vy = 0, vz = 0) {
    return this.sendPacket('PLAYER_TRANSFORM', { x, y, z, yaw, pitch, vx, vy, vz });
  }

  broadcastPlayerDamage(targetId, amount, attackerId = null) {
    return this.sendPacket('PLAYER_DAMAGE', { targetId, amount, attackerId: attackerId || this.clientId });
  }

  broadcastChatMessage(text, senderName = 'Player') {
    return this.sendPacket('CHAT_MESSAGE', { text, senderName });
  }

  broadcastGameEvent(eventName, data = {}) {
    return this.sendPacket('GAME_EVENT', { eventName, data });
  }

  // --- Packet Handlers ---

  onPacket(type, handler) {
    if (!this.packetListeners.has(type)) {
      this.packetListeners.set(type, new Set());
    }
    this.packetListeners.get(type).add(handler);
  }

  offPacket(type, handler) {
    const set = this.packetListeners.get(type);
    if (set) set.delete(handler);
  }

  handleIncomingPacket(packet) {
    if (!packet || typeof packet !== 'object') return;
    const { type, payload, sender } = packet;

    // Filter out our own packets
    if (sender && this.clientId && sender === this.clientId) {
      return;
    }

    const handlers = this.packetListeners.get(type);
    if (handlers) {
      handlers.forEach((fn) => fn(payload, sender, packet));
    }

    const wildcard = this.packetListeners.get('*');
    if (wildcard) {
      wildcard.forEach((fn) => fn(payload, sender, packet));
    }

    // Default world mutation routing if GameManager is attached
    if (this.gm) {
      this.applyToGameManager(type, payload, sender);
    }
  }

  applyToGameManager(type, payload, sender) {
    if (!this.gm) return;
    switch (type) {
      case 'BLOCK_PLACE':
        if (this.gm.world && typeof this.gm.world.setBlock === 'function') {
          this.gm.world.setBlock(payload.x, payload.y, payload.z, payload.blockType);
          this.gm.world.rebuildMeshes?.();
        }
        break;
      case 'BLOCK_BREAK':
        if (this.gm.world && typeof this.gm.world.setBlock === 'function') {
          this.gm.world.setBlock(payload.x, payload.y, payload.z, 0);
          this.gm.world.rebuildMeshes?.();
        }
        break;
      case 'PLAYER_TRANSFORM':
        if (this.gm.updateRemotePlayer && sender) {
          this.gm.updateRemotePlayer(sender, payload);
        }
        break;
      case 'PLAYER_DAMAGE':
        if (this.gm.applyDamage) {
          this.gm.applyDamage(payload.targetId, payload.amount, payload.attackerId);
        }
        break;
    }
  }
}
