/**
 * Registers the Voxel.io ServiceWorker for offline play.
 * @param {string} [swUrl='/sw.js']
 * @returns {Promise<ServiceWorkerRegistration|null>}
 */
export async function registerVoxelOfflineWorker(swUrl = '/sw.js') {
  if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
    try {
      const registration = await navigator.serviceWorker.register(swUrl, { scope: '/' });
      console.log('[Voxel.io] Offline ServiceWorker active with scope:', registration.scope);
      return registration;
    } catch (err) {
      console.warn('[Voxel.io] ServiceWorker registration failed:', err);
      return null;
    }
  }
  return null;
}
