/**
 * Voxel.io Unified Hub UI & In-Game HUD
 * Responsive lobby, game selector cards, LAN/P2P room browser, dynamic HUD overlay, and credits.
 */

import { GAME_ROSTER } from '../modes/GameRoster.js';

export class VoxelHubUI {
  constructor(appContainer, callbacks = {}) {
    this.container = appContainer;
    this.callbacks = callbacks; // onSelectMode, onHostRoom, onJoinRoom, onDirectJoin, onLeaveToLobby
    this.activeView = 'HUB'; // 'HUB' | 'IN_GAME'
    this.currentModeInstance = null;
    this.notifications = [];

    this.render();
  }

  render() {
    this.container.innerHTML = `
      <div id="voxel-app" class="voxel-theme">
        <!-- TOP NAVIGATION -->
        <header class="voxel-header">
          <div class="voxel-brand" id="brand-home-btn">
            <img src="./logo.png" alt="Voxel.io Logo" class="voxel-logo" />
            <h1 class="voxel-title">Voxel.io</h1>
          </div>
          
          <div class="voxel-net-status" id="net-status-badge">
            <span class="status-dot green"></span>
            <span class="status-text" id="net-status-text">P2P Ready / Offline Supported</span>
          </div>

          <div class="voxel-header-actions">
            <button class="voxel-btn primary" id="btn-host-room">🎮 Host Room</button>
            <button class="voxel-btn secondary" id="btn-join-room">🔗 Join P2P / LAN</button>
            <button class="voxel-btn subtle" id="btn-show-credits">ℹ️ Credits</button>
          </div>
        </header>

        <!-- MAIN CONTENT AREA -->
        <main class="voxel-main" id="voxel-main-view">
          <!-- HERO BANNER -->
          <section class="voxel-hero">
            <div class="hero-content">
              <h2>Next-Gen 3D Voxel Universe</h2>
              <p>Play Bedwars, Arena PVP, Doors, Granny, Manhunt & Skywars directly in your browser. Serverless WebRTC P2P multiplayer, LAN discovery, and 100% offline bot play.</p>
            </div>
          </section>

          <!-- GAME ROSTER GRID -->
          <section class="voxel-roster-section">
            <div class="section-title-bar">
              <h3>Featured Game Modes</h3>
              <span class="mode-count">7 Playable Modes</span>
            </div>
            <div class="voxel-grid" id="game-roster-grid"></div>
          </section>
        </main>

        <!-- IN-GAME HUD OVERLAY (Hidden initially) -->
        <div class="voxel-hud" id="voxel-hud-overlay" style="display: none;">
          <div class="hud-top-bar">
            <div class="hud-mode-badge" id="hud-mode-title">Voxel.io Mode</div>
            <div class="hud-objective-panel" id="hud-objective-content"></div>
            <button class="voxel-btn small danger" id="btn-exit-game">Leave Match</button>
          </div>

          <div class="hud-center-crosshair">+</div>

          <div class="hud-bottom-bar">
            <div class="hud-vitals">
              <div class="health-bar-container">
                <div class="health-bar-fill" id="hud-health-fill" style="width: 100%;"></div>
                <span class="health-bar-text" id="hud-health-text">20 / 20 HP</span>
              </div>
            </div>
            
            <div class="hud-hotbar" id="hud-hotbar-slots">
              <div class="slot active">1</div>
              <div class="slot">2</div>
              <div class="slot">3</div>
              <div class="slot">4</div>
              <div class="slot">5</div>
              <div class="slot">6</div>
              <div class="slot">7</div>
              <div class="slot">8</div>
              <div class="slot">9</div>
            </div>
          </div>

          <!-- NOTIFICATION TOAST CONTAINER -->
          <div class="hud-toasts" id="hud-toast-container"></div>
        </div>

        <!-- MULTIPLAYER / LAN MODAL -->
        <div class="voxel-modal-backdrop" id="multiplayer-modal" style="display: none;">
          <div class="voxel-modal">
            <div class="modal-header">
              <h4>Direct P2P & LAN Multiplayer</h4>
              <button class="modal-close" id="modal-close-btn">&times;</button>
            </div>
            <div class="modal-body">
              <div class="tab-controls">
                <button class="tab-btn active" id="tab-btn-lan">Discovered LAN Rooms</button>
                <button class="tab-btn" id="tab-btn-direct">Direct IP:Port / Room Code</button>
              </div>

              <!-- LAN ROOMS LIST -->
              <div class="tab-content" id="tab-content-lan">
                <p class="tab-desc">Searching subnet on port 8766 & cross-tab BroadcastChannel...</p>
                <div class="lan-rooms-list" id="lan-rooms-container">
                  <div class="empty-state">No other rooms found on local network yet. Host a match below!</div>
                </div>
              </div>

              <!-- DIRECT CONNECT -->
              <div class="tab-content" id="tab-content-direct" style="display: none;">
                <label>Direct IP:Port (e.g. 192.168.1.100:8766)</label>
                <div class="input-group">
                  <input type="text" id="input-direct-ip" placeholder="192.168.1.100:8766" />
                  <button class="voxel-btn primary" id="btn-submit-direct-ip">Connect</button>
                </div>
                
                <hr style="border: 0; border-top: 1px solid #334; margin: 16px 0;" />
                
                <label>WebRTC P2P Room Code</label>
                <div class="input-group">
                  <input type="text" id="input-room-code" placeholder="VOXEL-8842" />
                  <button class="voxel-btn secondary" id="btn-submit-room-code">Join Room</button>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- CREDITS MODAL -->
        <div class="voxel-modal-backdrop" id="credits-modal" style="display: none;">
          <div class="voxel-modal">
            <div class="modal-header">
              <h4>About & Credits</h4>
              <button class="modal-close" id="credits-close-btn">&times;</button>
            </div>
            <div class="modal-body">
              <h5 style="color: #6ee7b7; font-size: 1.2rem; margin-bottom: 8px;">Voxel.io Next-Gen Client</h5>
              <p>A unified serverless voxel client powering Bedwars, Arena PVP, Doors, Granny, Manhunt, Skywars and Creative sandbox worlds directly in the web browser.</p>
              
              <div class="credits-box" style="background: rgba(16, 185, 129, 0.1); border: 1px solid #10b981; border-radius: 8px; padding: 12px; margin: 16px 0;">
                <p style="margin: 0; font-weight: bold; color: #10b981;">Special thanks to bloxd for original game concept and inspiration.</p>
              </div>

              <p style="font-size: 0.9rem; color: #94a3b8;">Built with WebRTC DataChannel P2P mesh, LAN Discovery, Offline ServiceWorker CacheStorage, and modular voxel physics.</p>
            </div>
          </div>
        </div>

        <!-- FOOTER -->
        <footer class="voxel-footer">
          <div class="footer-links">
            <a href="https://voxel.io" target="_blank">Voxel.io Portal</a>
            <span class="separator">&bull;</span>
            <a href="javascript:void(0)" id="footer-credits-link">Credits & Inspiration</a>
            <span class="separator">&bull;</span>
            <span class="offline-badge">Offline PWA Capable</span>
          </div>
          <p class="footer-attribution">Special thanks to bloxd for original game concept and inspiration</p>
        </footer>
      </div>
    `;

    this.bindEvents();
    this.renderGameCards();
  }

  bindEvents() {
    // Brand click
    document.getElementById('brand-home-btn')?.addEventListener('click', () => {
      this.callbacks.onLeaveToLobby?.();
    });

    // Exit match
    document.getElementById('btn-exit-game')?.addEventListener('click', () => {
      this.callbacks.onLeaveToLobby?.();
    });

    // Multiplayer modal
    const modal = document.getElementById('multiplayer-modal');
    document.getElementById('btn-join-room')?.addEventListener('click', () => {
      modal.style.display = 'flex';
    });
    document.getElementById('modal-close-btn')?.addEventListener('click', () => {
      modal.style.display = 'none';
    });

    // Host room
    document.getElementById('btn-host-room')?.addEventListener('click', () => {
      this.callbacks.onHostRoom?.('bedwars');
    });

    // Tabs
    const tabLan = document.getElementById('tab-btn-lan');
    const tabDirect = document.getElementById('tab-btn-direct');
    const contentLan = document.getElementById('tab-content-lan');
    const contentDirect = document.getElementById('tab-content-direct');

    tabLan?.addEventListener('click', () => {
      tabLan.classList.add('active');
      tabDirect.classList.remove('active');
      contentLan.style.display = 'block';
      contentDirect.style.display = 'none';
    });

    tabDirect?.addEventListener('click', () => {
      tabDirect.classList.add('active');
      tabLan.classList.remove('active');
      contentDirect.style.display = 'block';
      contentLan.style.display = 'none';
    });

    // Direct IP Connect
    document.getElementById('btn-submit-direct-ip')?.addEventListener('click', () => {
      const val = document.getElementById('input-direct-ip')?.value?.trim();
      if (val) {
        modal.style.display = 'none';
        this.callbacks.onDirectJoin?.(val);
      }
    });

    // Room Code Connect
    document.getElementById('btn-submit-room-code')?.addEventListener('click', () => {
      const code = document.getElementById('input-room-code')?.value?.trim();
      if (code) {
        modal.style.display = 'none';
        this.callbacks.onJoinRoom?.(code);
      }
    });

    // Credits modal
    const creditsModal = document.getElementById('credits-modal');
    document.getElementById('btn-show-credits')?.addEventListener('click', () => {
      creditsModal.style.display = 'flex';
    });
    document.getElementById('footer-credits-link')?.addEventListener('click', () => {
      creditsModal.style.display = 'flex';
    });
    document.getElementById('credits-close-btn')?.addEventListener('click', () => {
      creditsModal.style.display = 'none';
    });
  }

  renderGameCards() {
    const grid = document.getElementById('game-roster-grid');
    if (!grid) return;

    grid.innerHTML = GAME_ROSTER.map((game) => `
      <div class="voxel-card" data-mode="${game.id}">
        <div class="card-thumb-wrapper">
          <img src="./${game.thumbnail}" alt="${game.name}" class="card-thumb" onerror="this.src='./logo.png'" />
          <span class="card-category">${game.category}</span>
          <span class="card-players">Max: ${game.maxPlayers}</span>
        </div>
        <div class="card-body">
          <h4 class="card-title">${game.name}</h4>
          <p class="card-desc">${game.description}</p>
          <div class="card-tags">
            ${game.tags.map((t) => `<span class="tag-pill">${t}</span>`).join('')}
          </div>
          <button class="voxel-btn primary full-width btn-launch-game" data-mode="${game.id}">
            Play ${game.name}
          </button>
        </div>
      </div>
    `).join('');

    // Attach click events
    grid.querySelectorAll('.btn-launch-game').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const modeId = btn.getAttribute('data-mode');
        this.callbacks.onSelectMode?.(modeId);
      });
    });
  }

  showInGameView(modeInstance) {
    this.activeView = 'IN_GAME';
    this.currentModeInstance = modeInstance;
    document.getElementById('voxel-main-view').style.display = 'none';
    document.getElementById('voxel-hud-overlay').style.display = 'flex';
    document.getElementById('hud-mode-title').textContent = modeInstance.name;
  }

  showHubView() {
    this.activeView = 'HUB';
    this.currentModeInstance = null;
    document.getElementById('voxel-main-view').style.display = 'block';
    document.getElementById('voxel-hud-overlay').style.display = 'none';
  }

  updateLanRooms(rooms) {
    const container = document.getElementById('lan-rooms-container');
    if (!container) return;

    if (!rooms || rooms.length === 0) {
      container.innerHTML = `<div class="empty-state">No other rooms found on local network yet. Host a match to broadcast!</div>`;
      return;
    }

    container.innerHTML = rooms.map((r) => `
      <div class="lan-room-card">
        <div class="room-info">
          <span class="room-name">${r.hostName || r.roomCode}</span>
          <span class="room-meta">${r.gameMode.toUpperCase()} &bull; ${r.players}/${r.maxPlayers} Players &bull; ${r.ip}:${r.port}</span>
        </div>
        <button class="voxel-btn primary small btn-lan-join" data-code="${r.roomCode}" data-ip="${r.ip}" data-port="${r.port}">
          Join
        </button>
      </div>
    `).join('');

    container.querySelectorAll('.btn-lan-join').forEach((btn) => {
      btn.addEventListener('click', () => {
        const modal = document.getElementById('multiplayer-modal');
        if (modal) modal.style.display = 'none';
        const ip = btn.getAttribute('data-ip');
        const port = btn.getAttribute('data-port');
        this.callbacks.onDirectJoin?.(`${ip}:${port}`);
      });
    });
  }

  updateHud(data, player) {
    if (this.activeView !== 'IN_GAME') return;

    // Update Health
    const hp = player?.hp ?? 20;
    const maxHp = player?.maxHp ?? 20;
    const pct = Math.max(0, Math.min(100, (hp / maxHp) * 100));
    const fill = document.getElementById('hud-health-fill');
    const text = document.getElementById('hud-health-text');
    if (fill) fill.style.width = `${pct}%`;
    if (text) text.textContent = `${hp} / ${maxHp} HP`;

    // Update Objectives
    const objPanel = document.getElementById('hud-objective-content');
    if (!objPanel || !data) return;

    if (data.mode === 'Bedwars' && data.teams) {
      objPanel.innerHTML = `
        <div class="objective-teams">
          <span class="team-badge ${data.teams.red.alive ? 'alive' : 'dead'}">R: ${data.teams.red.alive ? 'Bed' : 'X'}</span>
          <span class="team-badge ${data.teams.blue.alive ? 'alive' : 'dead'}">B: ${data.teams.blue.alive ? 'Bed' : 'X'}</span>
          <span class="team-badge ${data.teams.green.alive ? 'alive' : 'dead'}">G: ${data.teams.green.alive ? 'Bed' : 'X'}</span>
          <span class="team-badge ${data.teams.yellow.alive ? 'alive' : 'dead'}">Y: ${data.teams.yellow.alive ? 'Bed' : 'X'}</span>
        </div>
      `;
    } else if (data.mode === 'Arena PVP') {
      objPanel.innerHTML = `
        <div class="objective-arena">
          <span>Kit: <b>${data.kit}</b></span> | 
          <span>Kills: <b>${data.kills}</b></span> | 
          <span>Streak: <b>${data.streak}</b></span>
        </div>
      `;
    } else if (data.mode === 'Doors') {
      objPanel.innerHTML = `
        <div class="objective-doors">
          <span>Door: <b>${data.door}</b></span> | 
          <span>Gold: <b>${data.gold}</b></span> | 
          <span>Key: <b>${data.hasKey ? 'YES' : 'NO'}</b></span> |
          <span>${data.isHiding ? '🙈 Hiding' : '🏃 Roaming'}</span>
          ${data.rush ? '<span class="warning-tag">⚠️ RUSH INCOMING!</span>' : ''}
        </div>
      `;
    } else if (data.mode === 'Granny') {
      objPanel.innerHTML = `
        <div class="objective-granny">
          <span>Day: <b>${data.day}/${data.maxDays}</b></span> | 
          <span>Noise: <b>${data.noise}%</b></span> | 
          <span>Granny: <b>${data.grannyAlert}</b></span> |
          <span>Door: <b>${data.frontDoorProgress}</b></span>
        </div>
      `;
    } else if (data.mode === 'Manhunt') {
      objPanel.innerHTML = `
        <div class="objective-manhunt">
          <span>Role: <b>${data.role}</b></span> | 
          <span>Compass: <b>${data.compassBearing}&deg; (${data.compassDistance}m)</b></span> | 
          <span>Eyes: <b>${data.eyes}</b></span> |
          <span>Portal: <b>${data.portal}</b></span>
        </div>
      `;
    } else if (data.mode === 'Skywars' || data.mode === 'Creative') {
      objPanel.innerHTML = `
        <div class="objective-skywars">
          <span>Mode: <b>${data.mode}</b></span> | 
          ${data.alive !== undefined ? `<span>Alive: <b>${data.alive}</b></span>` : ''}
          ${data.flying !== undefined ? `<span>Flying: <b>${data.flying ? 'ON' : 'OFF'}</b></span>` : ''}
        </div>
      `;
    }
  }

  showNotification(msg, type = 'info') {
    const container = document.getElementById('hud-toast-container');
    if (!container) return;

    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    toast.textContent = msg;
    container.appendChild(toast);

    setTimeout(() => {
      toast.classList.add('fade-out');
      setTimeout(() => toast.remove(), 400);
    }, 2800);
  }
}
